window.WEEKS = {};
const W = window.WEEKS;

W[1] = {tema:"Hola, soy yo", objetivo:"Saludar, presentarte, decir de donde eres y tu edad; numeros 0-20.",
  escritura:{consigna:"Presentate: nombre, edad, pais, ciudad y profesion. Usa am / is / are.", min:30},
  inmersion:"Mira 15 min de 'English with Lucy' o 'BBC Learning English - Beginner' en YouTube. Repite en voz alta cada saludo que escuches.",
  lectura:{titulo:"Hello, I'm Diego", texto:`Hello! My name is Diego. I am from Chile. I am thirty years old. I am a photographer and video editor. My city is Santiago. It is a big city. My best friend is Tom. He is from Canada. He is a teacher. We are very good friends. Tom is very funny and kind. Where are you from? What is your name?`,
  preguntas:[{q:"Where is Diego from?",o:["Canada","Chile","Peru"],a:1},{q:"What is Tom's job?",o:["Photographer","Teacher","Doctor"],a:1},{q:"How old is Diego?",o:["Twenty","Thirteen","Thirty"],a:2},{q:"Is Santiago a small city?",o:["Yes, it is","No, it isn't"],a:1}]}};

W[2] = {tema:"Mi familia y mi gente", objetivo:"Describir a tu familia y amigos: aspecto, caracter y profesion.",
  escritura:{consigna:"Describe a 3 personas de tu familia: quien es, como se llama, como es (fisico y caracter) y su trabajo.", min:45},
  inmersion:"Mira un episodio de 'Peppa Pig' en ingles (si, en serio: ingles claro y lento) o 'Easy English' en YouTube. Anota 5 palabras nuevas.",
  lectura:{titulo:"My family", texto:`This is my family. My mother's name is Carmen. She is a nurse. She is short and very kind. My father is Jorge. He is an engineer. He is tall and funny. I have one sister and one brother. My sister, Sofia, is a student. She is very smart. Her eyes are green and her hair is black. My brother is married. His wife is from Argentina. They have two children, a boy and a girl. Their dog is big and friendly. We are a happy family.`,
  preguntas:[{q:"What is Carmen's job?",o:["Engineer","Nurse","Student"],a:1},{q:"What is Jorge like?",o:["Short and serious","Tall and funny","Young and sad"],a:1},{q:"Where is the brother's wife from?",o:["Chile","Spain","Argentina"],a:2},{q:"How many children does the brother have?",o:["One","Two","Three"],a:1}]}};

W[3] = {tema:"Mi dia a dia", objetivo:"Describir tu rutina completa con horas y dias.",
  escritura:{consigna:"Describe tu rutina de un dia normal, desde que te levantas hasta que te acuestas. Incluye horas.", min:60},
  inmersion:"Busca en YouTube 'my daily routine in English' (nivel principiante) y mira 2 videos. Pausa y repite cada frase.",
  lectura:{titulo:"A day in my life", texto:`I usually get up at seven o'clock. First, I take a shower and brush my teeth. Then I have breakfast. I drink coffee and eat bread with cheese. At half past eight, I go to work by bus. I work in an office in the center of the city. I start work at nine and I finish at six. I have lunch at one o'clock with my colleagues. In the evening, I go to the gym or I walk in the park. I have dinner at nine. After dinner, I watch a series or I read. I go to bed at eleven. On the weekend, I sleep late and I visit my parents on Sunday.`,
  preguntas:[{q:"What time does the person get up?",o:["At six","At seven","At eight"],a:1},{q:"How does the person go to work?",o:["By car","On foot","By bus"],a:2},{q:"When does the person have lunch?",o:["At one","At nine","At six"],a:0},{q:"What does the person do on Sunday?",o:["Works","Visits their parents","Goes to the gym"],a:1}]}};

W[4] = {tema:"Comida, compras y restaurantes", objetivo:"Pedir en un restaurante, comprar en una tienda y hablar de gustos de comida.",
  escritura:{consigna:"Que comes en un dia normal? Que comida te gusta y cual no? Escribe un dialogo corto pidiendo en un restaurante.", min:70},
  inmersion:"Mira 'Ordering food in English' (cualquier canal para principiantes). Practica el dialogo en voz alta 3 veces haciendo los dos papeles.",
  lectura:{titulo:"At the restaurant", texto:`Waiter: Good evening. Are you ready to order?
Ana: Yes, please. I would like the chicken with rice.
Waiter: And for you, sir?
Tom: I don't eat meat. Do you have any fish?
Waiter: Yes, we have grilled fish with salad. It's very fresh.
Tom: Great. I'll have the fish, please.
Waiter: Anything to drink?
Ana: A glass of red wine, please.
Tom: Just water for me. Does the fish come with potatoes?
Waiter: No, it doesn't, but you can order some.
Tom: OK, some potatoes, please.
Later...
Ana: Excuse me, can we have the bill, please?
Waiter: Of course. That's forty-five dollars.
Tom: Can I pay by card?
Waiter: Yes, of course.`,
  preguntas:[{q:"What does Ana order?",o:["Fish","Chicken with rice","Salad"],a:1},{q:"Why doesn't Tom order meat?",o:["He doesn't eat meat","It's expensive","There isn't any"],a:0},{q:"What does Tom drink?",o:["Wine","Juice","Water"],a:2},{q:"How much is the bill?",o:["$45","$54","$15"],a:0}]}};

W[5] = {tema:"Mi casa y mi ciudad", objetivo:"Describir donde vives, pedir y dar direcciones.",
  escritura:{consigna:"Describe tu casa o departamento y tu barrio: que hay, donde esta cada cosa, que te gusta y que no.", min:80},
  inmersion:"Abre Google Maps en ingles (cambia el idioma) y 'pasea' por Londres o Nueva York con Street View describiendo en voz alta lo que ves: There is a..., next to...",
  lectura:{titulo:"My neighborhood", texto:`I live in a small apartment on the fourth floor of a modern building. There are two bedrooms, a living room, a kitchen and a bathroom. My favorite room is the living room because there is a big window and the light is perfect for editing videos. My neighborhood is quiet and clean. There is a small park in front of my building and there are many trees. Next to the park, there is a cafe. The coffee is very good and it's cheap. There isn't a supermarket near my house, but there is a market on Saturdays. The subway station is two blocks from my building. To get there, you go straight on, turn left at the traffic light and the station is on the right, between a bank and a pharmacy. I love my neighborhood, but the rent is expensive.`,
  preguntas:[{q:"Why is the living room the favorite room?",o:["It's big","It has a big window and good light","It has a TV"],a:1},{q:"What is in front of the building?",o:["A cafe","A park","A bank"],a:1},{q:"Is there a supermarket near the house?",o:["Yes, there is","No, there isn't"],a:1},{q:"Where is the station?",o:["Between a bank and a pharmacy","Next to the park","Behind the cafe"],a:0}]}};

W[6] = {tema:"Tiempo libre y habilidades", objetivo:"Hablar de pasatiempos, frecuencia y lo que sabes o no sabes hacer.",
  escritura:{consigna:"Que haces en tu tiempo libre y con que frecuencia? Que sabes hacer y que no (can/can't)? Que quieres aprender?", min:90},
  inmersion:"Elige un YouTuber de viajes en ingles (ej.: 'Kara and Nate', 'Lost LeBlanc') y mira 15 min con subtitulos en INGLES. No en espanol.",
  lectura:{titulo:"Travel, cameras and music", texto:`In my free time I love traveling and making videos. I always take my camera with me. I usually go to the mountains or to the beach on the weekend. I often go hiking with my friends, and sometimes we go camping. I can swim well, but I can't surf. I want to learn this year! I also like music. I can play the guitar a little, but I can't sing. My girlfriend sings very well. We often play music together on Friday nights. I rarely watch TV because I think it's boring, but I really enjoy watching series in English. It's fun and I learn a lot of new words. I never play video games. How about you? What do you do in your free time?`,
  preguntas:[{q:"What does the writer always take with him?",o:["His guitar","His camera","His bike"],a:1},{q:"What can't he do?",o:["Swim","Surf","Play the guitar"],a:1},{q:"How often does he watch TV?",o:["Always","Often","Rarely"],a:2},{q:"Who sings very well?",o:["His girlfriend","His friend","He does"],a:0}]}};

W[7] = {tema:"Ropa y compras", objetivo:"Comprar ropa, hablar de tallas y precios, describir lo que llevas puesto ahora.",
  escritura:{consigna:"Describe que llevas puesto hoy y que usas normalmente. Escribe un dialogo comprando una chaqueta (talla, color, precio).", min:100},
  inmersion:"Mira un video de 'street interview' en ingles (ej. 'Easy English' o 'What are people wearing in New York'). Escucha 2 veces: primero sin subtitulos, luego con subtitulos en ingles.",
  lectura:{titulo:"Shopping for a trip", texto:`It's Saturday morning and Laura is at the mall. She is looking for clothes for her trip to Patagonia. It's summer in Santiago, but it's always cold in the south, so she needs a warm jacket and boots. She usually wears dresses and sneakers, but today she is wearing jeans and a T-shirt because she wants to try on a lot of clothes. "Can I help you?" asks the shop assistant. "Yes, I'm looking for a waterproof jacket," says Laura. "What size are you?" "Medium, I think." Laura tries on a blue jacket, but it is too tight. The large one fits perfectly. "How much is it?" "It's ninety dollars, but today there is a twenty percent discount." "Great! I'll take it. Can I pay by card?" Now Laura is smiling. She is ready for her adventure.`,
  preguntas:[{q:"Why does Laura need a warm jacket?",o:["It's winter in Santiago","It's cold in Patagonia","She is cold now"],a:1},{q:"What is Laura wearing today?",o:["A dress","Jeans and a T-shirt","A jacket"],a:1},{q:"What was the problem with the medium jacket?",o:["Too expensive","Too tight","Wrong color"],a:1},{q:"How much is the discount?",o:["10%","20%","90%"],a:1}]}};

W[8] = {tema:"Mi fin de semana (pasado)", objetivo:"Contar que hiciste en el pasado con was/were y verbos regulares. CHECKPOINT MES 2.",
  escritura:{consigna:"Cuenta tu ultimo fin de semana en orden: first, then, after that, finally. Como estuvo?", min:110},
  inmersion:"Escucha 1 episodio de '6 Minute English' (BBC Learning English). Escuchalo 2 veces y escribe 5 frases que entendiste.",
  lectura:{titulo:"A lazy Sunday that wasn't lazy", texto:`Last weekend was amazing. On Saturday morning I was very tired, so I stayed in bed until ten. Then I cleaned my apartment and cooked lunch for my sister. In the afternoon we walked to the park and talked for hours. In the evening I wanted to stay at home, but my friends called me. There was a party at Pedro's house! We danced all night and I arrived home at three in the morning. On Sunday I planned a lazy day, but it didn't happen. My parents visited me at eleven. We watched an old movie and laughed a lot. After that, it rained, so we stayed inside and played cards. Finally, I edited a short video of the weekend and uploaded it. It was a great weekend, but on Monday I was really tired!`,
  preguntas:[{q:"What did the writer do on Saturday morning?",o:["Went to a party","Stayed in bed until ten","Visited his parents"],a:1},{q:"Where was the party?",o:["At Pedro's house","At the park","At his apartment"],a:0},{q:"Who visited him on Sunday?",o:["His friends","His sister","His parents"],a:2},{q:"Why did they stay inside?",o:["It rained","They were tired","It was cold"],a:0}]}};

W[9] = {tema:"Viajes y aventuras", objetivo:"Contar un viaje completo con verbos irregulares; preguntar por el viaje de otros.",
  escritura:{consigna:"Cuenta tu mejor viaje: adonde fuiste, con quien, cuanto tiempo, que hiciste, que comiste, que salio mal.", min:120},
  inmersion:"Mira un vlog de viaje en ingles (25 min) con subtitulos en ingles. Elige 10 frases y haz shadowing (repetir encima del audio).",
  lectura:{titulo:"Lost in Cusco", texto:`Two years ago, I went to Peru with my best friend, Martin. We flew from Santiago to Lima and then we took a bus to Cusco. The journey was very long, almost twenty hours, but the landscape was incredible. In Cusco we stayed in a cheap hostel in the old town. On the first day, I felt sick because of the altitude, so I drank a lot of coca tea and slept all afternoon. The next day we did a city tour with a local guide. He told us amazing stories about the Incas. In the evening, we went out to find a restaurant, but we got lost in the small streets. My phone had no battery and Martin left his map at the hostel! Luckily, we met a family who spoke a little English. They showed us the way and recommended a fantastic restaurant. I ate alpaca for the first time. Three days later, we woke up at four in the morning and saw the sunrise at Machu Picchu. I took hundreds of photos. It was an unforgettable trip.`,
  preguntas:[{q:"How did they get from Lima to Cusco?",o:["By plane","By bus","By train"],a:1},{q:"Why did the writer feel sick?",o:["The food","The altitude","The bus"],a:1},{q:"Why did they get lost?",o:["No battery and no map","The guide left","It was dark"],a:0},{q:"What did the writer eat for the first time?",o:["Ceviche","Alpaca","Guinea pig"],a:1}]}};

W[10] = {tema:"Clima y naturaleza", objetivo:"Comparar lugares, climas y paisajes; describir la naturaleza.",
  escritura:{consigna:"Compara dos lugares que conozcas (clima, paisaje, gente, precios). Cual es el mejor lugar que has visitado y por que?", min:130},
  inmersion:"Mira un documental corto de naturaleza en ingles (ej. 'Our Planet' o canal 'BBC Earth'), 20 min, subtitulos en ingles.",
  lectura:{titulo:"From the driest desert to the coldest ice", texto:`Chile is one of the most surprising countries in the world. It is more than four thousand kilometers long, but it is only about one hundred and eighty kilometers wide on average. Because it is so long, the weather changes a lot from north to south. In the north there is the Atacama Desert, the driest desert in the world. Some parts never get rain, and at night the sky is so clear that it's the best place on Earth to see the stars. The center of the country has a warm, dry summer and a cool, rainy winter. It's similar to the climate in California. In the south, everything is greener and wetter. There are huge forests, deep lakes and active volcanoes. Patagonia, at the end of the country, is colder and windier than any other region. The glaciers there are enormous, but they are getting smaller every year because of climate change. For photographers, Chile is a dream: you can film a desert, a volcano and a glacier in the same trip.`,
  preguntas:[{q:"Why does the weather change a lot in Chile?",o:["It's very wide","It's very long","It's near the sea"],a:1},{q:"What is special about the Atacama at night?",o:["It's very hot","It's the best place to see stars","It rains"],a:1},{q:"Which region is the coldest and windiest?",o:["The north","The center","Patagonia"],a:2},{q:"What is happening to the glaciers?",o:["They are growing","They are getting smaller","They are moving north"],a:1}]}};

W[11] = {tema:"Planes y futuro", objetivo:"Hablar de planes, intenciones, predicciones y hacer citas.",
  escritura:{consigna:"Cuales son tus planes para los proximos 6 meses y para los proximos 5 anos? Usa going to, will y presente continuo.", min:140},
  inmersion:"Escucha 2 episodios de '6 Minute English' o 'Luke's English Podcast' (episodios cortos). Anota cada vez que escuches 'going to' o 'will'.",
  lectura:{titulo:"The plan", texto:`Next year is going to be the most important year of my life. I've decided to start my own travel channel on YouTube, and I'm going to make all my videos in English. Why English? Because I want to reach a global audience. Right now, my English isn't very good, but I'm studying every day and I'm sure it will improve quickly. My plan is simple. First, I'm going to save money for six months. Then, in July, I'm flying to Mexico. I'm staying with a friend in Oaxaca for two weeks. After that, I'll probably travel to Guatemala and Costa Rica by bus. I'm not sure yet. I'll decide when I get there. I think it will be difficult at the beginning. Maybe nobody will watch my first videos. But I promise I won't give up. I'm going to upload one video every week, no matter what. My friends think I'm crazy. Maybe they're right, but I can't wait to start!`,
  preguntas:[{q:"Why will the videos be in English?",o:["His friends speak English","To reach a global audience","It's easier"],a:1},{q:"What is he going to do first?",o:["Fly to Mexico","Save money","Buy a camera"],a:1},{q:"Where is he staying in Oaxaca?",o:["In a hotel","With a friend","In a hostel"],a:1},{q:"How often will he upload videos?",o:["Every day","Every week","Every month"],a:1}]}};

W[12] = {tema:"Salud y cuerpo", objetivo:"Explicar sintomas, ir al medico, dar y pedir consejos, hablar de habitos.",
  escritura:{consigna:"Escribe un email a un amigo que esta estresado y duerme mal. Dale 6 consejos usando should, have to, must y shouldn't.", min:150},
  inmersion:"Mira 'At the doctor - English conversation' en YouTube. Luego mira 15 min de una serie de medicos (ej. 'Grey's Anatomy') con subtitulos en ingles.",
  lectura:{titulo:"Doctor, I can't sleep", texto:`Patient: Good morning, doctor.
Doctor: Good morning. What's the problem?
Patient: I can't sleep well. I go to bed at midnight, but I wake up at three and I can't fall asleep again. I'm always tired and I have headaches.
Doctor: How long have you had this problem?
Patient: About two months. I started a new job and I have a lot of stress.
Doctor: Do you drink coffee?
Patient: Yes, about five cups a day. And I usually check my phone in bed.
Doctor: OK. First, you should drink less coffee, and you mustn't drink it after four in the afternoon. You should also stop using your phone an hour before bed. The light from the screen affects your brain.
Patient: Do I have to take any medicine?
Doctor: No, you don't have to take pills right now. But you have to exercise at least three times a week. Walking is enough. And try to go to bed at the same time every day.
Patient: What if it doesn't work?
Doctor: Come back in a month and we'll do some tests. But I'm sure you'll feel better soon.`,
  preguntas:[{q:"What time does the patient wake up?",o:["At midnight","At three","At four"],a:1},{q:"What caused the stress?",o:["A new job","His family","Exams"],a:0},{q:"What mustn't he do?",o:["Exercise","Drink coffee after 4 p.m.","Walk"],a:1},{q:"Does he have to take pills?",o:["Yes, he does","No, he doesn't"],a:1}]}};

W[13] = {tema:"Trabajo y estudios", objetivo:"Hablar de tu experiencia, logros y trabajo actual con present perfect.",
  escritura:{consigna:"Escribe sobre tu vida profesional: que has hecho, que has logrado, que no has hecho todavia y que quieres lograr.", min:160},
  inmersion:"Mira una charla TED corta (5-10 min) sobre trabajo o creatividad con subtitulos en ingles. Escribe un resumen de 3 frases.",
  lectura:{titulo:"A career change", texto:`Valentina is thirty-two and she has just changed her career completely. For eight years, she worked as an accountant in a big company in Santiago. The salary was good, but she was never happy. "I spent my days in front of spreadsheets. I've always loved photography, but I never had time for it," she says. Two years ago, she started taking online courses at night. Since then, she has finished five courses in photography and video editing, and she has built a small portfolio. Last month, she quit her job. "Have I been scared? Of course. I've never worked freelance before, and I don't have a fixed income yet." So far, she has already worked with three clients: a restaurant, a hotel and a local clothing brand. She hasn't earned as much as before, but she has learned more in two months than in eight years in the office. "My family thought I was crazy. Now my mother has seen my work and she's proud of me. That's the best achievement so far."`,
  preguntas:[{q:"What was Valentina's previous job?",o:["Photographer","Accountant","Teacher"],a:1},{q:"How many courses has she finished?",o:["Two","Five","Eight"],a:1},{q:"How many clients has she worked with?",o:["None","Three","Five"],a:1},{q:"What is her best achievement so far?",o:["Her salary","Her mother is proud of her","Her new office"],a:1}]}};

W[14] = {tema:"Tecnologia y redes sociales", objetivo:"Hablar de tecnologia, redes, habitos digitales y duracion (for/since).",
  escritura:{consigna:"Tu relacion con la tecnologia: que apps usas, desde cuando, cuanto tiempo pasas en redes, ventajas y desventajas.", min:170},
  inmersion:"Cambia el idioma de tu telefono y de Instagram/TikTok a ingles durante toda esta semana (y dejalo asi). Mira 20 min de un creador de contenido en ingles.",
  lectura:{titulo:"How I went viral", texto:`I've been a content creator since 2021, but for a long time nobody watched my videos. I posted a reel every week for almost two years and I had about five hundred followers. Then, last March, everything changed. I was in the south of Chile and I filmed a short clip with my drone of a waterfall in the middle of a forest. I edited it on my phone in ten minutes, added a trending song and uploaded it before going to sleep. When I woke up, my phone was crazy. The video had two hundred thousand views. By the end of the week, it had more than three million. I've gained fifty thousand followers since then, and several brands have contacted me. People often ask me what the secret is. Honestly, I don't know. I've made better videos than that one. What I've learned is that consistency is everything. If I had stopped after the first year, it would never have happened. Also, the first second is the most important: the hook. My advice? Post regularly, study the algorithm, but create content that you love.`,
  preguntas:[{q:"How long had the writer been posting before going viral?",o:["Two months","Almost two years","Five years"],a:1},{q:"What did the viral video show?",o:["A beach","A waterfall in a forest","A city"],a:1},{q:"How many followers has the writer gained since then?",o:["500","50,000","3 million"],a:1},{q:"According to the writer, what is the most important thing?",o:["An expensive camera","Consistency","Luck"],a:1}]}};

W[15] = {tema:"Historias y anecdotas", objetivo:"Narrar historias con pasado continuo, pasado perfecto y conectores. CHECKPOINT MES 4 (sem. 16-17).",
  escritura:{consigna:"Cuenta una anecdota real (algo divertido, peligroso o extrano que te paso). Usa while, when, suddenly, had already, luckily, in the end.", min:180},
  inmersion:"Escucha un episodio de 'The Moth' (historias reales contadas por personas) o 'English Learning for Curious Minds'. Resume la historia en voz alta en 1 minuto.",
  lectura:{titulo:"The night on the volcano", texto:`A few years ago, I was climbing the Villarrica volcano with two friends. We had planned the trip for months and we had checked the weather forecast many times. Everything looked perfect. We started walking at five in the morning. While we were climbing, the sun was rising and the snow was turning pink and orange. I was taking photos every five minutes. At about eleven, when we were almost at the top, the weather suddenly changed. A strong wind started blowing and a thick fog covered everything. We couldn't see more than two meters. Our guide told us that we had to go down immediately. At first, I was calm, but then I realized that my friend Camila wasn't behind me. We shouted her name again and again. Nobody answered. I have never been so scared in my life. After twenty terrible minutes, we heard a voice. Camila had taken a different path and had sat down behind a rock to wait. Luckily, she was OK, just very cold. In the end, we didn't reach the top, but we all got home safely. I still have the photos of that pink sunrise, and every time I look at them, I remember the fog.`,
  preguntas:[{q:"What were they doing when the weather changed?",o:["Going down","Almost at the top","Having breakfast"],a:1},{q:"What did the guide say?",o:["Keep climbing","Wait there","Go down immediately"],a:2},{q:"Where was Camila?",o:["At the top","Behind a rock","At the hotel"],a:1},{q:"Did they reach the top?",o:["Yes","No"],a:1}]}};

W[16] = {tema:"Cultura y gastronomia", objetivo:"Hablar de costumbres, tradiciones, comida tipica y modales; usar cuantificadores.",
  escritura:{consigna:"Explica a un extranjero 3 costumbres de tu pais y 2 platos tipicos (ingredientes, sabor, cuando se comen). Que costumbre extranjera te sorprendio?", min:190},
  inmersion:"Mira un episodio de un programa de comida en ingles (ej. 'Somebody Feed Phil' o 'Street Food' en Netflix) con subtitulos en ingles.",
  lectura:{titulo:"A foreigner's guide to Chilean manners", texto:`If you visit Chile, you'll notice a few customs that might surprise you. First of all, people greet each other with a kiss on the cheek, even when they meet someone for the first time. Men usually shake hands with other men, but between a man and a woman, one kiss is normal. Don't try two kisses like in Spain! Meals are also different. Lunch is the most important meal of the day and it can last a long time. Dinner is often lighter, and many families have "once" instead: tea, bread, avocado, cheese and ham, around eight in the evening. Chileans eat a lot of bread. In fact, they eat more bread per person than almost any country in the world. If someone invites you to their home, it's polite to bring something, such as wine or a dessert. Don't arrive exactly on time; arriving fifteen or twenty minutes late is completely normal, and arriving early might be a little awkward. In restaurants, a ten percent tip is usual, and the waiter will often ask you if you want to include it. Finally, be ready for a lot of slang. Chilean Spanish is fast and full of unique words. Even other Spanish speakers have few chances of understanding everything at first!`,
  preguntas:[{q:"How do a man and a woman usually greet in Chile?",o:["Two kisses","One kiss","A handshake"],a:1},{q:"What is 'once'?",o:["A light evening meal","Lunch","A dessert"],a:0},{q:"What is polite to bring to someone's home?",o:["Flowers only","Wine or a dessert","Nothing"],a:1},{q:"What is a normal tip?",o:["5%","10%","20%"],a:1}]}};

W[17] = {tema:"Relaciones y emociones", objetivo:"Expresar sentimientos, hablar de relaciones, condiciones reales (1er condicional).",
  escritura:{consigna:"Escribe una carta a tu 'yo' de dentro de 6 meses: como te sientes hoy aprendiendo ingles, tus miedos y que pasara si cumples (o no) tu meta.", min:200},
  inmersion:"Mira 2 episodios de 'Friends' (o 'Modern Family') con subtitulos en INGLES. Anota 5 expresiones sobre sentimientos.",
  lectura:{titulo:"Long distance", texto:`When Andres met Emily, he couldn't speak much English and she couldn't speak any Spanish. They met in a hostel in Bolivia. She was traveling around South America for six months, and he was filming a documentary about the salt flats. "At first, we communicated with gestures, a translation app and a lot of laughing," Andres remembers. After three weeks together, Emily had to go back to Australia. They promised they would keep in touch, but both of them were worried. "If we don't see each other for a year, will it work?" they asked themselves. They decided to try. For the next eighteen months they had video calls almost every day. Because of the time difference, Andres often woke up at five in the morning to talk to her. His English improved incredibly fast. "Love is the best teacher," he jokes. Of course, it wasn't always easy. They felt lonely and sometimes jealous, and they had a few arguments. But they trusted each other. Last year, Andres got a visa and moved to Melbourne. They're getting married in December. "If you really care about someone," he says, "distance is just a number."`,
  preguntas:[{q:"Where did Andres and Emily meet?",o:["In Australia","In Bolivia","In Chile"],a:1},{q:"How did they communicate at first?",o:["Perfect English","Gestures and an app","Spanish"],a:1},{q:"Why did Andres wake up at five?",o:["To work","Because of the time difference","To film"],a:1},{q:"What will happen in December?",o:["They will get married","He will move","They will travel"],a:0}]}};

W[18] = {tema:"Medios, cine y series", objetivo:"Recomendar y criticar peliculas y series; usar gerundios e infinitivos. Fin de fase 2.",
  escritura:{consigna:"Escribe una resena de tu pelicula o serie favorita: argumento (sin spoilers), personajes, que te gusto, que no y a quien se la recomiendas.", min:210},
  inmersion:"Elige UNA serie para el resto del plan y mirala siempre en ingles con subtitulos en ingles (sugerencias: 'Friends', 'The Office', 'Modern Family', 'Breaking Bad'). Minimo 30 min hoy.",
  lectura:{titulo:"Why you should stop watching dubbed movies", texto:`Most language teachers agree on one thing: watching series and movies in their original language is one of the best ways to improve your listening. Yet many people avoid doing it because they think it's too difficult. "I tried watching a series in English once, but I couldn't understand anything, so I stopped," is something teachers hear all the time. The problem is not the idea; it's the method. Experts suggest starting with something you've already seen in your own language. Since you know the plot, your brain can focus on the language instead of the story. Comedies like Friends or The Office are a good choice because the episodes are short and the conversations are about everyday situations. Another tip is to use English subtitles, not Spanish ones. Reading in your native language while listening to English means you'll be reading, not listening. With English subtitles, you connect the sound of words with how they are written. Finally, don't try to understand every word. Keep watching even when you feel lost. After a few weeks, you'll notice that you understand more and more without making any effort. It's worth trying: millions of people have learned English this way.`,
  preguntas:[{q:"Why do many people avoid watching series in English?",o:["It's expensive","They think it's too difficult","It's boring"],a:1},{q:"Why start with something you've already seen?",o:["It's cheaper","You know the plot and can focus on language","It's shorter"],a:1},{q:"Which subtitles does the article recommend?",o:["Spanish","None","English"],a:2},{q:"What should you do when you feel lost?",o:["Stop","Keep watching","Change to Spanish"],a:1}]}};

W[19] = {tema:"Medio ambiente", objetivo:"Hablar de problemas ambientales, causas y soluciones con voz pasiva. Inicio fase 3.",
  escritura:{consigna:"Ensayo corto: Cual es el mayor problema ambiental de tu pais? Causas, consecuencias y 3 soluciones. Usa la pasiva al menos 5 veces.", min:220},
  inmersion:"Mira un documental ambiental en ingles (ej. 'Before the Flood' o 'Our Planet') 30-40 min con subtitulos en ingles. Escribe 5 datos que aprendiste.",
  lectura:{titulo:"The glaciers are disappearing", texto:`Patagonia's glaciers are among the most beautiful places on the planet. Every year, they are visited by thousands of tourists who come to see the huge walls of blue ice. But scientists warn that these glaciers are disappearing faster than ever before. According to recent studies, most glaciers in the region have been losing mass for decades, and some have retreated several kilometers since the beginning of the twentieth century. The main cause is global warming. As temperatures rise, more ice is melted in summer than is created by snow in winter. The consequences are serious. Glaciers are a vital source of fresh water for many communities, and the melting ice is contributing to rising sea levels around the world. Ecosystems are also affected: rivers change, and some species are forced to move to new habitats. What can be done? Experts say that emissions must be reduced globally, and that is something no single country can solve alone. However, local actions also matter. In Chile, plastic bags were banned in 2019, national parks have been expanded, and more and more electricity is being produced by solar and wind power. "We can't save every glacier," says one researcher, "but if we act now, many of them will be protected for future generations."`,
  preguntas:[{q:"Who visits the glaciers every year?",o:["Only scientists","Thousands of tourists","Nobody"],a:1},{q:"What is the main cause of the melting?",o:["Tourism","Global warming","Earthquakes"],a:1},{q:"Why are glaciers vital?",o:["They are a source of fresh water","They attract tourists","They produce energy"],a:0},{q:"What was banned in Chile in 2019?",o:["Cars","Plastic bags","Tourism"],a:1}]}};

W[20] = {tema:"Dinero y emprendimiento", objetivo:"Hablar de finanzas, negocios y situaciones hipoteticas (2o condicional, wish).",
  escritura:{consigna:"Que harias si tuvieras 100.000 dolares? Que desearias cambiar de tu situacion economica (I wish...)? Describe el negocio que te gustaria crear.", min:230},
  inmersion:"Escucha un episodio de un podcast de negocios/emprendimiento en ingles (ej. 'How I Built This') 30 min. Escucha primero sin texto, luego con transcripcion.",
  lectura:{titulo:"If I were you, I'd charge more", texto:`Many freelance creators have the same problem: they love their work, but they don't earn enough money to live comfortably. Sebastian, a video editor from Valparaiso, was in that situation two years ago. "I was charging thirty dollars per video. I worked twelve hours a day and I still couldn't afford to pay my bills," he explains. Everything changed after a conversation with an older colleague. "He looked at my portfolio and said: 'Your work is excellent. If I were you, I'd triple my prices tomorrow.' I thought he was crazy. If I charged ninety dollars, nobody would hire me." But he tried. He lost two clients, but the others accepted the new rate without complaining. With the extra income, he was able to work fewer hours, invest in better equipment and spend more time improving his skills. Today he has a small agency with three employees. "I wish I had done it earlier," he says. "The biggest mistake creators make is thinking that a low price is a competitive advantage. It isn't. If your work has value, your price should reflect it." His advice for beginners? "Keep a budget, save at least twenty percent of every invoice for taxes, and never work for free, even for friends. Well, maybe for your mom."`,
  preguntas:[{q:"How much did Sebastian charge per video at first?",o:["$30","$90","$12"],a:0},{q:"What did his colleague advise?",o:["To quit","To triple his prices","To find more clients"],a:1},{q:"What happened when he raised his prices?",o:["He lost all his clients","He lost two clients","Nothing changed"],a:1},{q:"What does he wish?",o:["That he had done it earlier","That he had more employees","That he were rich"],a:0}]}};

W[21] = {tema:"Ciudad y sociedad", objetivo:"Debatir temas sociales y urbanos; definir y describir con oraciones de relativo.",
  escritura:{consigna:"Describe la ciudad ideal donde te gustaria vivir y comparala con tu ciudad actual. Usa who, which, where, whose al menos 6 veces.", min:240},
  inmersion:"Mira un video explicativo de 'Vox' o 'Johnny Harris' (YouTube) sobre ciudades o sociedad. Sin subtitulos la primera vez; con subtitulos en ingles la segunda.",
  lectura:{titulo:"The 15-minute city", texto:`Imagine a city where everything you need is fifteen minutes away from your home: the school where your children study, the shop where you buy your food, the doctor who takes care of your family, and the park where you go running. This is the idea behind the "15-minute city," a concept which has become popular in urban planning in recent years. It was made famous by Carlos Moreno, a professor whose ideas inspired the mayor of Paris. Supporters say the model has many advantages. People who don't need to drive every day spend less time in traffic, have more free time and produce fewer emissions. Local businesses, which often struggle to compete with big malls, get more customers. Neighborhoods become safer and more connected, because people walk more and know their neighbors. However, critics argue that the idea is difficult to apply in cities which have grown without planning, like many in Latin America. In places where rich and poor neighborhoods are far apart, the best schools, hospitals and jobs are concentrated in a few areas. "A 15-minute city is great for people who can already afford to live in the right place," says one urban expert. "The real challenge is making it possible for everyone." For many cities, the question is not whether the idea is good, but how to make it fair.`,
  preguntas:[{q:"What is the main idea of a 15-minute city?",o:["Faster cars","Everything you need is 15 minutes from home","Shorter work days"],a:1},{q:"Whose ideas inspired the mayor of Paris?",o:["Carlos Moreno's","A doctor's","A student's"],a:0},{q:"What is one advantage for local businesses?",o:["Lower taxes","More customers","Bigger buildings"],a:1},{q:"What do critics say?",o:["It's too expensive","It's difficult in unplanned cities","It's boring"],a:1}]}};

W[22] = {tema:"Creatividad y creacion de contenido", objetivo:"Hablar de tu trabajo creativo, feedback y clientes; contar lo que otros dijeron (estilo indirecto).",
  escritura:{consigna:"Cuenta una conversacion con un cliente, jefe o amigo sobre un proyecto usando estilo indirecto: que te dijo, que te pidio, que le respondiste.", min:250},
  inmersion:"Mira un tutorial de DaVinci Resolve o de edicion de video COMPLETAMENTE en ingles (ej. 'Casey Faris', 'Justin Odisho'). Aprende algo nuevo y anota el vocabulario tecnico.",
  lectura:{titulo:"The client who hated the music", texto:`Last month I had a project with a hotel in the Atacama Desert. The marketing manager, Claudia, sent me a very clear brief. She told me that they wanted a sixty-second video for Instagram and that the main idea was "luxury and silence." She said the deadline was the following Friday and asked me if I could deliver a rough cut by Wednesday. I spent two days filming at golden hour and at night under the stars. The footage was amazing. I edited the first version and chose an epic orchestral track, because I thought it would make the video more cinematic. On Wednesday, Claudia called me. She said she loved the images, but she hated the music. "We asked for silence," she reminded me, "and this sounds like a superhero movie." At first, I felt embarrassed. Then I realized she was completely right. I had focused on what I liked, not on what the client wanted. I told her I would send a new version the next day. This time I used only natural sounds: the wind, footsteps on the sand, a glass of wine, and a very soft piano at the end. When she watched it, she wrote me a message saying it was exactly what they had imagined. The lesson? Read the brief twice, and remember that the music sets the mood more than any shot.`,
  preguntas:[{q:"What was the main idea of the brief?",o:["Adventure","Luxury and silence","Fun"],a:1},{q:"What did Claudia say about the first version?",o:["She loved everything","She loved the images but hated the music","She hated the images"],a:1},{q:"What music did the writer use the first time?",o:["Soft piano","Natural sounds","An epic orchestral track"],a:2},{q:"What lesson did the writer learn?",o:["Film more","Read the brief twice","Use more music"],a:1}]}};

W[23] = {tema:"Ciencia y futuro", objetivo:"Hacer predicciones sobre el futuro, deducir y especular.",
  escritura:{consigna:"Como sera el mundo en 2050? Haz predicciones sobre trabajo, tecnologia, viajes y tu propia vida. Usa will be -ing, will have + participio, might, must.", min:260},
  inmersion:"Mira un video de 'Kurzgesagt - In a Nutshell' o 'Veritasium' con subtitulos en ingles. Miralo 2 veces y explica la idea principal en voz alta.",
  lectura:{titulo:"Will AI take our jobs?", texto:`It's one of the most common questions of our time: will artificial intelligence take our jobs? The honest answer is that nobody knows for certain, but experts have some ideas. Most researchers agree that by 2035, AI will have changed almost every profession in some way. Tasks that are repetitive and predictable, such as data entry, basic translation or simple customer service, are the most likely to be automated. Many of the people who do those jobs today will be doing something different in ten years. However, history suggests that technology usually creates new jobs while it destroys old ones. When cameras became cheap and digital, some people thought professional photographers would disappear. Instead, millions of new jobs appeared: content creators, social media managers, video editors. Something similar might happen with AI. The jobs that are least likely to be replaced are those that require creativity, empathy, physical skills or complex decision-making. A nurse who comforts a patient, a guide who tells a story or an editor who understands the emotion of a scene can't be replaced easily. That said, the people who learn to use AI tools will probably have a big advantage over those who don't. "AI won't replace you," says a popular phrase, "but a person who uses AI might." If that's true, the most important skill of the future must be the ability to keep learning.`,
  preguntas:[{q:"Which tasks are most likely to be automated?",o:["Creative tasks","Repetitive and predictable tasks","Physical tasks"],a:1},{q:"What happened when digital cameras became cheap?",o:["Photographers disappeared","Many new jobs appeared","Nothing"],a:1},{q:"Which jobs are least likely to be replaced?",o:["Data entry","Jobs needing creativity and empathy","Basic translation"],a:1},{q:"According to the text, what might be the most important skill?",o:["Programming","The ability to keep learning","Speaking many languages"],a:1}]}};

W[24] = {tema:"Opinion y debate", objetivo:"Argumentar, contrastar ideas y expresar arrepentimientos (3er condicional).",
  escritura:{consigna:"Ensayo de opinion: 'Es mejor aprender un idioma viviendo en el extranjero o estudiando en casa?' Introduccion, 2 argumentos a favor, 1 en contra, conclusion. Usa however, although, despite, moreover, therefore.", min:270},
  inmersion:"Mira un debate o entrevista larga en ingles (ej. un clip de un podcast como 'Diary of a CEO') 30 min. Anota 5 conectores que usen los hablantes.",
  lectura:{titulo:"Is social media good for travel?", texto:`Few industries have been transformed by social media as much as tourism. On the one hand, platforms like Instagram and TikTok have made travel more accessible than ever. Thanks to creators who share tips, budgets and hidden places, millions of people have discovered destinations they would never have heard of otherwise. Small towns that used to be ignored now receive visitors, and local businesses have benefited enormously. Moreover, travelers can now plan safer and cheaper trips with information that is free and up to date. On the other hand, critics argue that social media has created serious problems. Some places have become so popular that they are now overcrowded. In certain viewpoints, people wait for hours just to take the same photo that thousands of others have already posted. Despite the beauty of the landscape, the experience can feel artificial. Furthermore, the pressure to share every moment may stop travelers from actually enjoying where they are. Although these concerns are real, the answer is probably not to stop sharing, but to share more responsibly. Many creators now avoid revealing the exact location of fragile places, and promote respect for local communities. As one travel writer put it: "If I had known how a single viral photo could change a village, I would have been much more careful." In conclusion, social media is a tool. Whether it harms or helps travel depends on how we use it.`,
  preguntas:[{q:"What is one advantage of social media for travel?",o:["Places are more crowded","People discover new destinations","Travel is more expensive"],a:1},{q:"What is one problem mentioned?",o:["Overcrowded places","Expensive flights","Bad photos"],a:0},{q:"What do many creators do now?",o:["Stop posting","Avoid revealing the exact location of fragile places","Charge more"],a:1},{q:"What is the conclusion?",o:["Social media is bad","It depends on how we use it","We should stop traveling"],a:1}]}};

W[25] = {tema:"Mundo profesional y entrevistas", objetivo:"Hacer una entrevista de trabajo en ingles, escribir emails formales, dominar phrasal verbs clave.",
  escritura:{consigna:"Escribe un email formal postulando a un trabajo de editor de video en una empresa de Canada: presentacion, experiencia, habilidades, por que tu, cierre formal.", min:280},
  inmersion:"Mira 'Job interview in English - questions and answers' y graba tus propias respuestas a 5 preguntas (Tell me about yourself, strengths, weaknesses, achievement, why us).",
  lectura:{titulo:"Tell me about yourself", texto:`Interviewer: Thanks for coming in today. Let's start with an easy one. Tell me about yourself.
Candidate: Sure. I'm a video editor and content creator from Chile. I have a background in photography, and for the last five years I've been working freelance with hotels, restaurants and travel brands. I'm mainly in charge of editing and color grading, but I also deal with clients directly, from the first brief to the final version.
Interviewer: Why are you interested in this position?
Candidate: I've followed your company's work for a long time, and I love how you use storytelling in travel content. I'm used to working alone, and I'd like to take up the challenge of working in a creative team and learning from more experienced people.
Interviewer: What would you say is your main strength?
Candidate: I'd say I'm very reliable. I always meet deadlines, even when I have to work under pressure. Clients also say I'm good at figuring out what they really want, even when the brief isn't very clear.
Interviewer: And a weakness?
Candidate: To be honest, I used to have trouble saying no. I took on too many projects and I ran out of time. I've worked on that by planning my week carefully and setting up a clear system for priorities.
Interviewer: Great. Do you have any questions for us?
Candidate: Yes. What does a typical day look like for the team, and how do you give feedback on projects?
Interviewer: Good question. Let me explain...`,
  preguntas:[{q:"What is the candidate's background?",o:["Accounting","Photography","Marketing"],a:1},{q:"Why is the candidate interested in the position?",o:["Better salary","To work in a creative team and learn","To work from home"],a:1},{q:"What is the candidate's main strength?",o:["Being reliable","Speaking languages","Programming"],a:0},{q:"What weakness did the candidate mention?",o:["Arriving late","Having trouble saying no","Being shy"],a:1}]}};

W[26] = {tema:"Fluidez total: tu historia en ingles", objetivo:"Integrar todo: contar tu historia de 6 meses, hablar 5+ minutos sin parar. EXAMEN FINAL.",
  escritura:{consigna:"Texto final: cuenta tu viaje de 6 meses aprendiendo ingles. Como empezaste, que fue dificil, que has logrado, que harias diferente y cuales son tus proximas metas (C1).", min:300},
  inmersion:"Mira una pelicula completa en ingles con subtitulos en ingles (o sin subtitulos si te atreves). Luego graba un video de 3 minutos contando de que trata.",
  lectura:{titulo:"Six months later", texto:`Six months ago, I couldn't introduce myself in English. I remember feeling embarrassed when a tourist asked me for directions and all I could say was "sorry, no English." Today, I'm writing this text without a dictionary. It hasn't been easy. There were weeks when I felt that I wasn't making any progress at all. I've been studying almost every day, sometimes for three hours, sometimes for just twenty minutes on a bad day. But I never broke the chain for more than two days. The first two months were the hardest. Everything was new, and my brain hurt after every lesson. Around month three, something changed: I started understanding YouTube videos without subtitles. In month four, I had my first real conversation with a native speaker, a traveler I met in Valparaiso. We talked for an hour. I made a lot of mistakes, but she understood me, and that was the moment I knew it was working. If I had to start again, I would do a few things differently. I would speak from day one, even if I sounded ridiculous. I would also have stopped watching series in Spanish much earlier. My next goal is to reach C1: I want to understand everything without subtitles and work with international clients. I know there's still a long way to go, but looking back at how far I've come, I'm proud of myself. Consistency beats talent. Whatever happens, I'm going to keep going.`,
  preguntas:[{q:"What could the writer say six months ago?",o:["A full introduction","Only 'sorry, no English'","Nothing"],a:1},{q:"When did the writer start understanding YouTube without subtitles?",o:["Month one","Around month three","Month six"],a:1},{q:"What would the writer do differently?",o:["Study less","Speak from day one","Use more apps"],a:1},{q:"What is the writer's next goal?",o:["Reach C1","Move abroad","Stop studying"],a:0}]}};

